                    trial_date, venue, trial_time, status, is_published)
select * from (values
  ($pfc$Mumbai$pfc$, $pfc$Maharashtra$pfc$, $pfc$U-14 to U-19$pfc$, $pfc$Open Trial$pfc$, 24, 12, current_date + 14, $pfc$Cooperage Ground$pfc$, $pfc$7:00 AM — 11:00 AM$pfc$, 'open'::trial_status, true),
  ($pfc$Delhi NCR$pfc$, $pfc$Delhi$pfc$, $pfc$U-12 to U-17$pfc$, $pfc$Academy Partner$pfc$, 20, 8, current_date + 21, $pfc$Chhatrasal Stadium$pfc$, $pfc$7:00 AM — 11:00 AM$pfc$, 'open'::trial_status, true),
  ($pfc$Bengaluru$pfc$, $pfc$Karnataka$pfc$, $pfc$U-14 to U-21$pfc$, $pfc$Open Trial$pfc$, 30, 20, current_date + 28, $pfc$Bangalore Football Stadium$pfc$, $pfc$7:00 AM — 11:00 AM$pfc$, 'open'::trial_status, true),
  ($pfc$Kolkata$pfc$, $pfc$West Bengal$pfc$, $pfc$U-13 to U-19$pfc$, $pfc$Academy Partner$pfc$, 18, 6, current_date + 35, $pfc$Rabindra Sarobar Stadium$pfc$, $pfc$7:00 AM — 11:00 AM$pfc$, 'open'::trial_status, true)
