-- Delete this section if you don't want sample records.

insert into tutors (user_id, specialization, positions, experience_years, bio, city)
select id, $pfc$Attacking play & finishing$pfc$, $pfc${Striker,Winger,"Attacking Mid"}$pfc$::text[], 7.0,
       $pfc$Former state-level striker. Seven years coaching academy intakes across Kerala and Karnataka.$pfc$,
       $pfc$Kochi$pfc$
from app_users where login_id = $pfc$COACH-DEMO$pfc$
