insert into clients (user_id, full_name, age, position, city, state, phone,
                     guardian_name, guardian_phone, height_cm, weight_kg, goal,
                     tutor_id, plan_id, subscription_status, subscription_start,
                     subscription_end, status)
select u.id, $pfc$Arjun Nair$pfc$, 16, $pfc$Striker$pfc$, $pfc$Pune$pfc$, $pfc$Maharashtra$pfc$,
       $pfc$919000000002$pfc$, $pfc$Sunita Nair$pfc$, $pfc$919000000003$pfc$, 172.0, 61.5,
       $pfc$Trial-ready for U-17 academy intake$pfc$,
       (select id from tutors limit 1),
       (select id from plans where slug = $pfc$pro$pfc$),
       'active'::sub_status, current_date - 60, current_date + 30, 'active'::client_status
from app_users u where u.login_id = $pfc$PFC-DEMO$pfc$
on conflict (user_id) do nothing;

-- ═══ 7. DEMO TRAINING, SCORES, PAYMENTS ═══
-- Wrapped so it only runs once, and only if the demo athlete exists.
do $do$
declare
  v_client uuid;
  v_tutor  uuid;
  v_plan   uuid;
  v_trial  uuid;
begin
  select c.id, c.tutor_id, c.plan_id into v_client, v_tutor, v_plan
  from clients c join app_users u on u.id = c.user_id
  where u.login_id = $pfc$PFC-DEMO$pfc$;

  if v_client is null then return; end if;
  if exists (select 1 from progress_records where client_id = v_client) then return; end if;

  -- a 12-week training block
  insert into training_assignments
    (client_id, tutor_id, title, description, sessions_per_week,
     start_date, end_date, status, progress_pct)
  values (v_client, v_tutor, $pfc$12-Week Striker Block$pfc$,
          $pfc$Finishing under pressure, first touch in tight space, movement off the last defender.$pfc$,
          4, current_date - 56, current_date + 28, 'in_progress'::assignment_status, 62);

  -- four progress reviews showing a clear upward trend
  insert into progress_records
    (client_id, tutor_id, recorded_on, speed, stamina, technique, strength, agility, weight_kg, notes)
  values
    (v_client, v_tutor, current_date - 56, 48, 52, 44, 40, 47, 64.0,
     $pfc$Baseline assessment. Good engine, technique needs the most work.$pfc$),
    (v_client, v_tutor, current_date - 35, 61, 66, 55, 49, 58, 63.0, $pfc$Sharper first touch.$pfc$),
    (v_client, v_tutor, current_date - 14, 74, 80, 68, 62, 71, 62.0, $pfc$Big jump in stamina.$pfc$),
    (v_client, v_tutor, current_date - 2,  82, 88, 76, 71, 79, 61.5,
     $pfc$Trial-ready on movement. Still loses the aerial duel — strength block next.$pfc$);

  -- recent sessions
  insert into training_sessions
    (client_id, tutor_id, session_date, duration_min, focus, drills, attendance, coach_rating, notes)
  values
    (v_client, v_tutor, current_date - 2, 75, $pfc$Finishing under pressure$pfc$,
     $pfc$["Near-post finishes x30","First-time volleys x20","1v1 vs keeper x15"]$pfc$::jsonb, 'present'::attendance_status, 8,
     $pfc$Composure improved. Rushed three of the last five.$pfc$),
    (v_client, v_tutor, current_date - 5, 60, $pfc$Ball mastery$pfc$,
     $pfc$["Cone weave x20","Sole rolls 3min","Wall pass two-touch"]$pfc$::jsonb, 'present'::attendance_status, 9, $pfc$Best session yet.$pfc$),
    (v_client, v_tutor, current_date - 9, 45, $pfc$Recovery + mobility$pfc$,
     $pfc$["Hip mobility flow","Light jog 20min"]$pfc$::jsonb, 'late'::attendance_status, 7, null);

  -- subscription + two payments
  insert into subscriptions (client_id, plan_id, plan_name, cycle, amount, status, start_date, end_date)
  values (v_client, v_plan, $pfc$Pro$pfc$, 'monthly'::billing_cycle, 3499, 'active'::sub_status,
          current_date - 60, current_date + 30);

  insert into payments (client_id, amount, method, status, paid_on, period_start, period_end, invoice_no)
  values
    (v_client, 3499, $pfc$upi$pfc$, 'paid'::payment_status, current_date - 60, current_date - 60, current_date - 30, $pfc$PFC-2026-001$pfc$),
    (v_client, 3499, $pfc$upi$pfc$, 'paid'::payment_status, current_date - 30, current_date - 30, current_date + 1,  $pfc$PFC-2026-014$pfc$);

  -- booked onto the nearest trial
  select id into v_trial from trials order by trial_date limit 1;
  if v_trial is not null then
    insert into trial_registrations (trial_id, client_id, status)
    values (v_trial, v_client, 'confirmed'::registration_status)
    on conflict (trial_id, client_id) do nothing;
  end if;
end $do$;

-- ═══ 8. REUSABLE TRAINING PROGRAMMES ═══
insert into training_programs (title, position, level, weeks, description, focus_areas)
select * from (values
  ($pfc$12-Week Striker Block$pfc$, $pfc$Striker$pfc$, $pfc$Intermediate$pfc$, 12,
   $pfc$Ball mastery first, then finishing under fatigue.$pfc$,
   $pfc${"First touch","Movement off the last defender","Finishing under pressure"}$pfc$::text[]),
  ($pfc$Winger Explosiveness$pfc$, $pfc$Winger$pfc$, $pfc$Intermediate$pfc$, 10,
   $pfc$1v1 beats, crossing accuracy and change-of-direction speed.$pfc$,
   $pfc${"1v1 dribbling","Crossing","Acceleration"}$pfc$::text[]),
  ($pfc$Goalkeeper Fundamentals$pfc$, $pfc$Goalkeeper$pfc$, $pfc$Beginner$pfc$, 8,
   $pfc$Shot-stopping, distribution and one-on-one composure.$pfc$,
   $pfc${"Reflex saves","Distribution","Positioning"}$pfc$::text[])
) as p(title, position, level, weeks, description, focus_areas)
where not exists (select 1 from training_programs);

-- ═══ 9. WELCOME NOTICE ═══
insert into announcements (title, body, audience, is_published)
select $pfc$Welcome to the Proforma Co portal$pfc$,
       $pfc$Your trial calendar, training plan and performance scores all live here. Message your coach on WhatsApp if anything looks wrong.$pfc$,
       $pfc$all$pfc$, true
where not exists (select 1 from announcements);

commit;

